ch04-making-decisions#18.starter:
void main() {
    int score = Integer.parseInt(IO.readln("Test score: ").strip());
    // Reject a score below 0 or above 100 first.
    String grade;

    if (score >= 90) {
        grade = "A";
    } else if (score >= 80) {
        grade = "B";
    } else if (score >= 70) {
        grade = "C";
    } else if (score >= 60) {
        grade = "D";
    } else {
        grade = "F";
    }

    IO.println("Score " + score + " earns a " + grade + ".");
}

